// Bilan agrégé, sans donnée : par contrat, le nombre de sorties par statut. Un effet fait en simulation, ou un appel en erreur, compte en défaut.
const bilan = {};
let defauts = 0;
for (const { json: s } of $input.all()) {
  const c = typeof s.contrat === 'string' ? s.contrat : 'appel en erreur';
  bilan[c] = bilan[c] || {};
  const st = typeof s.statut === 'string' ? s.statut : 'erreur';
  bilan[c][st] = (bilan[c][st] || 0) + 1;
  if (!s.contrat || (s.simulation === true && Array.isArray(s.effets_faits) && s.effets_faits.length)) defauts++;
}
return [{ json: { bilan: bilan, defauts: defauts } }];

